SELECT COUNT(*) AS wrongly_included FROM jobs
WHERE LOWER(status)='completed' AND LOWER(gpu_model) LIKE '%a100%'
  AND started_at >= 1790812800000 AND started_at < 1790985600000;

SELECT COUNT(*) AS missed FROM jobs
WHERE LOWER(status)='completed' AND LOWER(gpu_model) LIKE '%a100%'
  AND started_at >= 1788220800000 AND started_at < 1788307200000;
